package fr.sophi.market.net;
import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.world.item.ItemStack;import java.util.*;
public final class SellPrices {private SellPrices(){} private static final Map<String,Integer>P=Map.ofEntries(Map.entry("minecraft:iron_ingot",12),Map.entry("minecraft:gold_ingot",18),Map.entry("minecraft:diamond",120),Map.entry("minecraft:emerald",85),Map.entry("minecraft:netherite_ingot",1200),Map.entry("minecraft:cobblestone",1),Map.entry("minecraft:stone",1),Map.entry("minecraft:coal",4)); public static int price(ItemStack s){var id=BuiltInRegistries.ITEM.getKey(s.getItem());if(id==null)return 0;var v=P.get(id.toString());if(v!=null)return v;String p=id.getPath();if(p.contains("paladium")||p.contains("palladium"))return 500;if(p.endsWith("_ingot"))return 15;if(p.endsWith("_gem"))return 25;if(p.contains("raw_")||p.endsWith("_ore"))return 8;return 0;}}
